options.spec:
params:
  gullFilters: { select: crossfilter }
plot:
  - mark: lineY
    data: { from: gullSteps }
    x: { bin: time, interval: day }
    y: { max: colony_km }
    z: bird
    stroke: 'rgba(128, 128, 128, 0.3)'
    strokeWidth: 1
  - mark: lineY
    data: { from: gullSteps, filterBy: $gullFilters }
    x: { bin: time, interval: day }
    y: { max: colony_km }
    z: bird
    stroke: '#4cc9f0'
    strokeWidth: 1.2
    strokeOpacity: 0.8
  - select: intervalY
    as: $gullFilters
    brush: { fillOpacity: 0.06, stroke: currentColor, strokeOpacity: 0.6 }
xDomain: Fixed
yDomain: Fixed
xLabel: null
yLabel: ↑ From the colony (km)
marginLeft: 52

params:
  gullFilters: { select: crossfilter }
plot:
  - mark: rectY
    data: { from: gullSteps }
    x: { bin: speed_kmh, step: 1 }
    y: { count: speed_kmh }
    fill: 'rgba(128, 128, 128, 0.3)'
    inset: 0.5
  - mark: rectY
    data: { from: gullSteps, filterBy: $gullFilters }
    x: { bin: speed_kmh, step: 1 }
    y: { count: speed_kmh }
    fill: '#ffb703'
    inset: 0.5
  - select: intervalX
    as: $gullFilters
    brush: { fillOpacity: 0.06, stroke: currentColor, strokeOpacity: 0.6 }
xDomain: [0, 40]
yScale: sqrt
xLabel: Speed (km/h) →
yLabel: ↑ Steps
marginLeft: 48

